use dbloja;
-- CARGA GRANDE E VARIADA PARA dbloja
-- Execute depois do seu DDL.
SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE tb_pagamento;
TRUNCATE TABLE tb_item_pedido;
TRUNCATE TABLE tb_pedido;
TRUNCATE TABLE tb_estoque;
TRUNCATE TABLE tb_produto;
TRUNCATE TABLE tb_categoria_produto;
TRUNCATE TABLE tb_contrato_fornecedor;
TRUNCATE TABLE tb_endereco;
TRUNCATE TABLE tb_email;
TRUNCATE TABLE tb_numero;
TRUNCATE TABLE tb_item_folha_pagamento;
TRUNCATE TABLE tb_folha_pagamento;
TRUNCATE TABLE tb_contrato_funcionario;
TRUNCATE TABLE tb_cargo_funcionario;
TRUNCATE TABLE tb_funcionario;
TRUNCATE TABLE tb_fornecedor;
TRUNCATE TABLE tb_cliente;
TRUNCATE TABLE tb_pessoa;
SET FOREIGN_KEY_CHECKS = 1;























































































-- Conferência rápida
SELECT 'pessoas' AS tabela, COUNT(*) AS total FROM tb_pessoa
UNION ALL SELECT 'clientes', COUNT(*) FROM tb_cliente
UNION ALL SELECT 'fornecedores', COUNT(*) FROM tb_fornecedor
UNION ALL SELECT 'funcionarios', COUNT(*) FROM tb_funcionario
UNION ALL SELECT 'produtos', COUNT(*) FROM tb_produto
UNION ALL SELECT 'pedidos', COUNT(*) FROM tb_pedido
UNION ALL SELECT 'itens_pedido', COUNT(*) FROM tb_item_pedido
UNION ALL SELECT 'pagamentos', COUNT(*) FROM tb_pagamento;